class LmdbPackedCacheValueOwnershipTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void actualPackedHitEmitsAnIsolatedTrustedAliasEachTime(@TempDir Path directory) {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		store.init();
		try {
			var runtime = ((LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics())
					.estimatorRuntime();
			var model = new LmdbPackedCostModel(runtime);
			var goal = OptimizationGoal.root();
			var context = LmdbCascadesOptimizer.cacheContext(null, EmptyBindingSet.getInstance(), goal, model, null,
					runtime);
			var cache = new PackedPlanCache(8, 1);
			RemoteBNode original = (RemoteBNode) RemoteBNode.newResponseScope(
					new BlankNodeAllocationScope("owned-", ignored -> false), VF, new Object(), true)
					.map(VF.createBNode("remote"));
			PackedPlanningResult cold = plan(cache, context, model, original);
			PackedPlanningResult first = plan(cache, context, model, original);
			assertFalse(cold.metrics().planCacheHit());
			assertTrue(first.metrics().planCacheHit(), "this must reach an actual backend-codec packed hit");
			RemoteBNode one = (RemoteBNode) constant(first.selectedPlan());
			assertEquals(original.getID(), one.getID());
			assertTrue(RemoteBNode.sameTrustedIdentity(original, one));
			assertNotSame(original, one, "a cache emission must not lend the caller's response registry");
			RemoteBNode two = (RemoteBNode) constant(plan(cache, context, model, original).selectedPlan());
			assertEquals(one.getID(), two.getID());
			assertTrue(RemoteBNode.sameTrustedIdentity(one, two));
			assertNotSame(one, two, "separate emissions require separate private mutable registries");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void actualPackedKeyAndTemplatePayloadUsesItsExistingBudget(@TempDir Path directory) {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		store.init();
		try {
			var runtime = ((LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics())
					.estimatorRuntime();
			var model = new LmdbPackedCostModel(runtime);
			var goal = OptimizationGoal.root();
			var context = LmdbCascadesOptimizer.cacheContext(null, EmptyBindingSet.getInstance(), goal, model, null,
					runtime);
			Value small = VF.createLiteral("small");
			long budget = PackedCacheCapacityTestSupport.smallCapacity(source(small), context, model,
					LmdbStatementPatternSemanticsCodec.INSTANCE);
			var cache = new PackedPlanCache(8, 1, budget);
			Value large = VF.createLiteral("Ā".repeat(Math.toIntExact(budget)));
			assertTrue(2L * large.stringValue().length() > budget);
			plan(cache, context, model, large);
			assertFalse(plan(cache, context, model, large).metrics().planCacheHit(),
					"a retained source/identity value alone exceeds the unchanged budget");
			assertFalse(plan(cache, context, model, small).metrics().planCacheHit());
			PackedPlanningResult hot = plan(cache, context, model, small);
			assertTrue(hot.metrics().planCacheHit(), "the same budget must retain real small packed queries");
			assertEquals(small, constant(hot.selectedPlan()));
		} finally {
			store.shutDown();
		}
	}

	private static PackedPlanningResult plan(PackedPlanCache cache, PackedPlanCache.Context context,
			LmdbPackedCostModel model, Value value) {
		return PackedCascadesPlanner.optimize(source(value), OptimizationGoal.root(), cache, context, model, null,
				LmdbStatementPatternSemanticsCodec.INSTANCE);
	}

	private static TupleExpr source(Value value) {
		return new QueryRoot(new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(value), "v")));
	}

	private static Value constant(TupleExpr plan) {
		Value[] value = { null };
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ValueConstant node) {
				assertTrue(value[0] == null, "the fixture has exactly one scalar constant");
				value[0] = node.getValue();
			}
		});
		assertTrue(value[0] != null);
		return value[0];
	}
}
